package com.seminarhub.domain.seminar.service;
import com.seminarhub.domain.seminar.domain.Seminar; import com.seminarhub.domain.seminar.repository.SeminarRepository; import com.seminarhub.global.dto.CursorRequest;
import java.util.List; import java.util.Optional; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class SeminarService { private final SeminarRepository repository;
@Transactional public Seminar save(Seminar e){return repository.save(e);} public Optional<Seminar> findById(Long id){return repository.findByIdAndDeletedAtIsNull(id);} public List<Seminar> findByIds(List<Long> ids){return repository.findAllByIdInAndDeletedAtIsNull(ids);} public List<Seminar> findAll(SeminarSearchQuery q){return repository.search(q);} public Page<Seminar> findAll(SeminarSearchQuery q,Pageable p){return repository.search(q,p);} public List<Seminar> findByCursor(SeminarSearchQuery q,CursorRequest c){return repository.search(q,c);} @Transactional public Seminar update(Seminar e,String name,String explanation,Long price,Long maxParticipants,Long participantsCount){e.update(name,explanation,price,maxParticipants,participantsCount);return e;} @Transactional public Seminar delete(Seminar e){e.delete();return e;} @Transactional public List<Seminar> deleteAll(List<Seminar> es){es.forEach(Seminar::delete);return es;} }
